# area: generics_variance
# hypothesis: PEP 695 infers covariance for a read-only Reader, so Reader[int] is accepted where Reader[float] is expected, while list[int] is rejected for list[float] because list is invariant.
from typing import reveal_type


class Reader[T]:
    def __init__(self, item: T) -> None:
        self._item = item

    def get(self) -> T:
        return self._item


def show_floats(r: Reader[float]) -> float:
    return r.get()


def fill(xs: list[float]) -> None:
    xs.append(1.5)


def biggest[T: (int, str)](a: T, b: T) -> T:
    return a if a >= b else b


ints = Reader(3)
print(show_floats(ints))
nums = [1, 2]
fill(nums)  # expect-error
print(nums)
reveal_type(biggest(2, 5))
print(biggest('a', 'b'))
try:
    print(biggest(2, 'x'))  # expect-error
except TypeError:
    print('mixed constraint')
